/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.9 Post delivery note
/// </summary>
internal final class METSalesOrderShipmentPackingSlipService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Main run method
/// </summary>
/// <returns>True if delivery note generated; otherwise, false</returns>
void run(METSalesOrderShipmentPackingSlipContract _contract)
{
    // update selected shipment records status to loaded
    this.updateShipmentStatus(_contract);
}

    /// <summary>
    /// Trigger the delivery note posting for selected shipments
    /// </summary>
    void updateShipmentStatus(METSalesOrderShipmentPackingSlipContract _contract)
    {
        MultiSelectionHelper    selection;
        METShipmentTable        shipmentTable, shipmentTableTmp;
        METShipmentLine         shipmentLine;
        boolean                 firstSO = true;
        SalesTable              salesTable, firstSalesTable;
        METSalesTable           metSalesTable;
        CustPackingSlipJour     custPackingSlipJour;
        CustPackingSlipTrans    custPackingSlipTrans;
        const str emptyString = '';
        boolean             moreRecords;
        RecordSortedList    shipmentTableList = _contract.parmShipmentTableRecordSortedList();

        Query query = new Query(QueryStr(SalesUpdate));

        shipmentTableTmp.setTmp();
        RecordInsertList shipmentTableTmpList = new RecordInsertList(tableNum(METShipmentTable));//CAR issue fix
        moreRecords = shipmentTableList.first(shipmentTable);
        
        // Loop through the recordSortedList sorted by route and route stop to create shipment ids
        while (moreRecords)
        {
            while select shipmentLine
                    join salesTable
                    join metSalesTable
                   where shipmentLine.ShipmentId == shipmentTable.ShipmentId
                      && salesTable.SalesId == shipmentLine.SalesId
                      && metSalesTable.SalesTable == salesTable.RecId
            {
                if (firstSO)
                {
                    firstSalesTable = salesTable;
                    firstSO = false;
                }

                // Exclude NDC orders from delivery note posting as it is already created before the shipment
                if (!metSalesTable.SecondaryInventLocationId)
                {
                    // Add RDC orders in the query for delivery note posting
                    query.dataSourceTable(tablenum(SalesTable)).addRange(fieldnum(SalesTable, SalesId)).value(shipmentLine.SalesId);
                }
                else
                {
                    // for NDC update the delivery note shipment and load ID
                    select firstonly custPackingSlipJour
                         exists join custPackingSlipTrans
                               where custPackingSlipTrans.SalesId == custPackingSlipJour.SalesId
                                  && custPackingSlipTrans.PackingSlipId == custPackingSlipJour.PackingSlipId
                                  && custPackingSlipTrans.DeliveryDate == custPackingSlipJour.DeliveryDate
                                  && custPackingSlipTrans.OrigSalesId == salesTable.SalesId
                                  && custPackingSlipJour.METLoadId == emptyString
                                  && custPackingSlipJour.METShipmentId == emptyString;

                    if (custPackingSlipJour)
                    {
                        custPackingSlipJour.selectForUpdate(true);
                        custPackingSlipJour.METLoadId = shipmentTable.LoadId;
                        custPackingSlipJour.METShipmentId = shipmentTable.ShipmentId;
                        custPackingSlipJour.update();
                    }
                }
            }

            shipmentTableTmp.ShipmentId = shipmentTable.ShipmentId;
            shipmentTableTmpList.add(shipmentTableTmp);//CAR report issue fix

            // select the next sales order from the soList
            moreRecords = shipmentTableList.next(shipmentTable);
        }
        shipmentTableTmpList.insertDatabase();//CAR report issue fix
        // trigger delivery note posting
        SalesFormLetter salesFormLetter = SalesFormLetter::construct(DocumentStatus::PackingSlip);
        salesFormLetter.salesTable  (SalesTable::find(firstSalesTable.SalesId));
        salesFormLetter.transDate   (DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
        salesFormLetter.proforma    (NoYes::No);
        salesFormLetter.sumBy       (AccountOrder::Account);
        salesFormLetter.parmShowDialog(false);

        // The delivery note posting will automatically print the delivery note reports using standard print management feature.
        salesFormLetter.printFormLetter(true);
        salesFormLetter.usePrintManagement(true);
        salesFormLetter.specQty     (SalesUpdate::PickingList);
        salesFormLetter.printout(Printout::After);
  
        // creating the query filtered by selected sales orders
        SysQueryRun queryRun = new SysQueryRun(query, true);
        salesFormLetter.chooseLinesQuery(queryRun);
        salesFormLetter.reArrangeNow(true);
        salesFormLetter.chooseLines();
        salesFormLetter.run();

        if (salesFormLetter.parmJournalRecord())
        {
            info("@MET:DeliveryNotePostingSucessful");

            // update shipments status to shipped
            update_recordset shipmentTable
            setting
            ShipmentStatus = WHSShipmentStatus::Shipped
            join shipmentTableTmp
                where shipmentTableTmp.ShipmentId == shipmentTable.ShipmentId;
        }
    }
